import { sb } from './api.js';

const app = document.querySelector('#app');
import { stages, followupTypes, activeStatus, fromEcuadorInput, ecuadorInput, ecuadorDay, dayGroups } from './domain.js';
const sources = ['Prospección propia','LinkedIn','Instagram','Referido','WhatsApp','Email','Llamada','Networking','Lead entregado por NextWebEC','Otro'];
const activityTypes = [['note','Nota'],['call','Llamada'],['whatsapp','WhatsApp'],['email','Email'],['meeting','Reunión'],['proposal','Propuesta enviada'],['response','Cliente respondió'],['other','Otro']];
let session, profile, leads=[], archivedLeads=[], services=[], profiles=[], profileNames=[], activities=[], sales=[], commissions=[], payments=[];
let followups=[],finance={},commissionRate=0.4,loadSequence=0;
let page='Dashboard', query='', filters={stage:'', owner:'', source:'', service:'', after:'', before:'', followup:''}, toastTimer;
const esc = (v='') => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n||0));
const date = v => v ? new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',day:'2-digit',month:'short',year:'numeric'}).format(/^\d{4}-\d{2}-\d{2}$/.test(String(v))?new Date(v+'T12:00:00-05:00'):new Date(v)) : '—';
const dt = v => v ? new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(v)) : '—';
const isAdmin = () => profile?.role === 'admin';
const labelStage = v => stages.find(s=>s[0]===v)?.[1] || v || 'Nuevo';
const person = id => profiles.find(p=>p.id===id)?.full_name || profileNames.find(p=>p.id===id)?.full_name || 'Colaborador';
const initials = name => (name||'N').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const notify = (message,error=false) => {let el=document.querySelector('.toast'); if(!el){el=document.createElement('div');app.append(el)}el.className=`toast${error?' error':''}`;el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3300)};
const errText = e => e?.message || 'No se pudo completar la acción. Intenta de nuevo.';
const initialsBrand = '<span class="brand-mark">N</span>';

sb.auth.onAuthStateChange((_event,next)=>{ session=next; if(next) loadApp(); else renderLogin(); });
sb.auth.getSession().then(({data,error})=>{ if(error) renderLogin(error.message); else {session=data.session; session?loadApp():renderLogin()} });

function renderLogin(error=''){app.innerHTML=`<main class="login-wrap"><form class="login-card" id="login-form"><div class="brand">${initialsBrand}<span>NextWebEC<small>CRM comercial</small></span></div><h1>Bienvenido</h1><p>Inicia sesión con tu cuenta de NextWebEC.</p>${error?`<div class="alert">${esc(error)}</div>`:''}<div class="field"><label for="email">Correo electrónico</label><input id="email" name="email" type="email" autocomplete="username" required placeholder="nombre@empresa.com"></div><div class="field"><label for="password">Contraseña</label><input id="password" name="password" type="password" autocomplete="current-password" required placeholder="Tu contraseña"></div><button class="btn primary" style="width:100%;margin-top:10px" type="submit">Entrar</button><p class="subtext" style="text-align:center;margin-top:18px">Acceso privado para el equipo comercial</p></form></main>`;
 document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const b=e.currentTarget.querySelector('button');b.disabled=true;b.textContent='Ingresando…';const {error}=await sb.auth.signInWithPassword({email:String(f.get('email')).trim().toLowerCase(),password:f.get('password')});if(error){renderLogin('Correo o contraseña incorrectos.');} };
}
async function loadApp(){
 if(!session)return;const sequence=++loadSequence;
 const first=!app.querySelector('.shell');if(first)app.innerHTML='<div class="boot">Cargando NextWebEC CRM…</div>';
 try{
 const {data:pr,error:pe}=await sb.from('profiles').select('*').eq('id',session.user.id).single();if(pe)throw pe;profile=pr;if(!pr.is_active){await sb.auth.signOut();throw new Error('Cuenta desactivada. Contacta al administrador.');}
 const {data,error}=await sb.rpc('workspace');if(error)throw error;if(sequence!==loadSequence)return;
 ({leads,services,profiles,activities,sales,commissions,payments,profileNames,followups,finance}=data);archivedLeads=data.archived;commissionRate=data.commission_rate;
 renderShell();
 }catch(e){if(!first){notify(errText(e),true);return;}app.innerHTML=`<main class="error-page"><h1>No se pudo abrir el CRM</h1><p>${esc(errText(e))}</p><button class="btn" id="retry">Volver a intentar</button><button class="btn" id="signout">Cerrar sesión</button></main>`;document.querySelector('#retry').onclick=loadApp;document.querySelector('#signout').onclick=()=>sb.auth.signOut();}
}
function renderShell(){const allowed=['Dashboard','Pipeline','Oportunidades','Seguimientos','Comisiones'];if(isAdmin())allowed.push('Archivados','Equipo','Configuración');if(!allowed.includes(page))page='Dashboard';
const nav=[['Dashboard','◫'],['Pipeline','▦'],['Oportunidades','☷'],['Seguimientos','◷'],['Comisiones','＄'],...(isAdmin()?[['Archivados','▤'],['Equipo','♙'],['Configuración','⚙']]:[])];
app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${initialsBrand}<span>NextWebEC<small>CRM comercial</small></span></div><div class="nav-label">Workspace</div><nav class="nav">${nav.map(([n,i])=>`<button data-page="${n}" class="${page===n?'active':''}"><span class="ico">${i}</span>${n}</button>`).join('')}</nav><div class="side-bottom"><div class="user-chip"><div class="avatar">${initials(profile.full_name)}</div><div class="user-meta"><b>${esc(profile.full_name)}</b><span>${isAdmin()?'Administrador':'Colaborador'}</span></div><button class="icon-btn" title="Cerrar sesión" id="logout">↪</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><b>${page}</b> <span class="hide-mobile">/ NextWebEC</span></div><div class="top-actions"><span class="avatar hide-mobile">${initials(profile.full_name)}</span><button class="btn primary" id="new-lead">＋ <span class="hide-mobile">Nueva oportunidad</span><span class="mobile-title">Nuevo</span></button></div></header>${isAdmin()?`<div class="mobile-admin"><label for="admin-nav">Administración</label><select id="admin-nav"><option value="">Ir a…</option>${["Archivados","Equipo","Configuración"].map(n=>`<option value="${n}" ${page===n?"selected":""}>${n}</option>`).join("")}</select></div>`:""}<section class="content" id="view"></section></main><nav class="mobile-nav">${nav.slice(0,5).map(([n,i])=>`<button data-page="${n}" class="${page===n?'active':''}"><span>${i}</span>${n==='Oportunidades'?'Leads':n}</button>`).join('')}<button id="logout-mobile"><span>↪</span>Salir</button></nav><div id="modal-root"></div></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;renderShell()});document.querySelector('#admin-nav')?.addEventListener('change',e=>{if(e.target.value){page=e.target.value;renderShell();}});document.querySelector('#new-lead').onclick=()=>openLeadForm();document.querySelector('#logout').onclick=()=>sb.auth.signOut();document.querySelector('#logout-mobile').onclick=()=>sb.auth.signOut();renderPage();}
function visibleLeads(){return leads.filter(l=>{if(query){const q=query.toLowerCase();if(![l.company_name,l.contact_name,l.phone,l.email,l.website,l.city].some(x=>String(x||'').toLowerCase().includes(q)))return false}if(filters.stage&&l.status!==filters.stage)return false;if(filters.owner&&l.owner_id!==filters.owner)return false;if(filters.source&&l.source!==filters.source)return false;if(filters.service&&l.service_id!==filters.service)return false;if(filters.after&&new Date(l.created_at)<new Date(filters.after+'T00:00:00-05:00'))return false;if(filters.before&&new Date(l.created_at)>new Date(filters.before+'T23:59:59-05:00'))return false;if(filters.followup==='pending'&&!l.next_action_at)return false;return true})}
function setView(html){document.querySelector('#view').innerHTML=html;}
function statsCards(items){return dashboardStats(items);}
function dashboardStats(items){
 const active=items.filter(l=>activeStatus(l.status));const pending=followups.filter(f=>f.status==='pending'&&leads.some(l=>l.id===f.lead_id&&!l.deleted_at));const grouped=dayGroups(pending);const overdue=pending.filter(f=>new Date(f.due_at)<new Date()).length;
 const pipeline=active.reduce((n,l)=>n+Math.round(Number(l.estimated_value||0)*100),0)/100;
 const metrics=isAdmin()?[
 ['Oportunidades totales',items.length,'Sin archivados'],['Oportunidades activas',active.length,'En proceso comercial'],['Vendedores activos',profiles.filter(p=>p.role==='executive'&&p.is_active).length,'Equipo comercial'],['Valor del pipeline',money(pipeline),'Valor potencial'],['Ventas ganadas',finance.won,'Incluye ventas archivadas'],['Valor vendido',money(finance.sold),'Ventas ganadas, incluidas archivadas'],['Dinero cobrado',money(finance.collected),'Solo cobros confirmados'],['Saldo por cobrar',money(finance.balance),'De ventas ganadas'],['Comisión generada',money(finance.generated),'Según tasa de cada venta'],['Comisión pagada',money(finance.paid),'Pagos registrados'],['Comisión pendiente',money(finance.pending),'Por pagar']
 ]:[['Mis oportunidades activas',active.length,'Prospectos en proceso'],['Seguimientos pendientes',pending.length,`${grouped.today.length} para hoy`],['Seguimientos vencidos',overdue,'Para retomar primero'],['Mis ventas ganadas',finance.won,'Proyectos cerrados'],['Valor vendido',money(finance.sold),'Valor final acordado'],['Dinero cobrado',money(finance.collected),'Cobros confirmados'],['Comisión generada',money(finance.generated),'Por dinero cobrado'],['Comisión pagada',money(finance.paid),'Pagos de administración'],['Comisión pendiente',money(finance.pending),'Por pagar']];
 return `<div class="grid stats">${metrics.map(([label,value,note])=>`<article class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`).join('')}</div>`;
}
function renderPage(){const items=visibleLeads();if(page==='Dashboard')renderDashboard(items);else if(page==='Pipeline')renderPipeline(items);else if(page==='Oportunidades')renderOpportunities(items);else if(page==='Seguimientos')renderFollowups(items);else if(page==='Comisiones')renderCommissions();else if(page==='Archivados'&&isAdmin())renderArchived();else if(page==='Equipo')renderTeam();else if(page==='Configuración')renderSettings();}
function renderDashboard(items){
 const active=leads.filter(l=>activeStatus(l.status));const pending=followups.filter(f=>f.status==='pending'&&leads.some(l=>l.id===f.lead_id&&!l.deleted_at));const group=dayGroups(pending);
 const day=[['Vencidos',pending.filter(f=>new Date(f.due_at)<new Date())],['Para hoy',group.today.filter(f=>new Date(f.due_at)>=new Date())],['Próximos',group.upcoming]];
 const silent=active.filter(l=>!l.last_contact_at).sort((a,b)=>idleDays(b)-idleDays(a));const attention=active.filter(l=>l.last_contact_at&&idleDays(l)>=3).sort((a,b)=>idleDays(b)-idleDays(a));
 setView(`<div class="page-head"><div><h1>Mi día</h1><p>${isAdmin()?'Seguimientos del equipo y oportunidades que requieren atención.':'Tus próximos pasos, en orden de prioridad.'}</p></div><button class="btn" data-page="Seguimientos">Ver seguimientos →</button></div><section class="panel day-panel">${day.map(([title,tasks])=>`<div class="day-group"><h2>${title} <span class="badge">${tasks.length}</span></h2>${tasks.slice(0,6).map(taskRow).join('')||'<p class="subtext">Todo al día. No hay seguimientos en este grupo.</p>'}</div>`).join('')}<div class="day-group"><h2>Sin actividad <span class="badge">${silent.length}</span></h2>${silent.slice(0,5).map(attentionRow).join('')||'<p class="subtext">Todas las oportunidades tienen actividad.</p>'}</div><div class="day-group"><h2>Requieren atención <span class="badge">${attention.length}</span></h2>${attention.slice(0,5).map(attentionRow).join('')||'<p class="subtext">No hay oportunidades abandonadas.</p>'}</div></section>${dashboardStats(leads)}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Resumen del pipeline</h2></div>${stages.map(([key,name])=>`<div class="pipeline-summary"><span>${name}</span><b>${leads.filter(x=>x.status===key).length}</b></div>`).join('')}</section>${isAdmin()?`<section class="panel"><div class="panel-head"><h2>Actividad del equipo</h2></div>${renderRanking()}</section>`:''}</div>`);
 wireCommon();wireTasks();
}
function filterBar(){return `<div class="toolbar"><div class="search"><input id="search" placeholder="Buscar empresa, contacto, teléfono o email…" value="${esc(query)}"></div><select id="filter-stage"><option value="">Todos los estados</option>${stages.map(([k,v])=>`<option value="${k}" ${filters.stage===k?'selected':''}>${v}</option>`).join('')}</select>${isAdmin()?`<select id="filter-owner"><option value="">Todos los vendedores</option>${profiles.filter(p=>p.role==='executive').map(p=>`<option value="${p.id}" ${filters.owner===p.id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select>`:''}<select id="filter-source"><option value="">Todas las fuentes</option>${sources.map(x=>`<option ${filters.source===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-service"><option value="">Todos los servicios</option>${services.map(x=>`<option value="${x.id}" ${filters.service===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select id="filter-followup"><option value="">Seguimientos</option><option value="pending" ${filters.followup==='pending'?'selected':''}>Con seguimiento pendiente</option></select><input id="filter-after" aria-label="Desde" type="date" value="${filters.after}"><input id="filter-before" aria-label="Hasta" type="date" value="${filters.before}"></div>`}
function rowLead(l){return `<tr data-open="${l.id}"><td>${date(l.created_at)}</td><td><span class="company">${esc(l.company_name)}</span><span class="subtext">${esc(l.services?.name||'Sin servicio')}</span></td><td>${esc(l.contact_name)}</td><td>${esc(l.phone||'—')}</td><td>${esc(l.profiles?.full_name||person(l.owner_id))}</td><td><span class="badge ${l.status==='won'?'green':l.status==='lost'?'red':'blue'}">${labelStage(l.status)}</span></td><td>${money(l.estimated_value)}</td><td>${dt(l.next_action_at)}</td><td>${dt(l.updated_at)}</td></tr>`}
function mobileLead(l){return `<article class="mobile-lead" data-open="${l.id}"><div class="mobile-lead-head"><div><h3>${esc(l.company_name)}</h3><p>${esc(l.contact_name)} · ${esc(l.phone||'Sin teléfono')}</p></div><span class="badge ${l.status==='won'?'green':l.status==='lost'?'red':'blue'}">${labelStage(l.status)}</span></div><div class="mobile-lead-foot"><span>${money(l.estimated_value)} · ${esc(l.profiles?.full_name||person(l.owner_id))}</span><span>${l.next_action_at?dt(l.next_action_at):'Sin seguimiento'}</span></div></article>`}
function renderOpportunities(items){setView(`<div class="page-head"><div><h1>Oportunidades</h1><p>Prospectos, etapas y próximos pasos en un solo lugar.</p></div>${isAdmin()?`<div><button class="btn" data-page="Archivados">Archivados</button> <button class="btn" id="export-csv">↓ Exportar CSV</button></div>`:''}</div>${filterBar()}<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Empresa</th><th>Contacto</th><th>Teléfono</th><th>Vendedor</th><th>Estado</th><th>Valor</th><th>Seguimiento</th><th>Última actividad</th></tr></thead><tbody>${items.map(rowLead).join('')}</tbody></table></div><div class="mobile-cards">${items.map(mobileLead).join('')}</div>${items.length?'':`<div class="empty"><strong>Aún no hay oportunidades</strong>Registra tu primer prospecto para empezar.</div>`}</section>`);wireCommon();document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>openDetail(el.dataset.open));document.querySelector('#export-csv')?.addEventListener('click',exportCsv)}
function renderArchived(){
  const q=query.toLowerCase();
  const items=archivedLeads.filter(l=>[l.company_name,l.contact_name,l.phone,l.email].some(v=>String(v||'').toLowerCase().includes(q)));
  setView(`<div class="page-head"><div><h1>Archivados</h1><p>Consulta el historial o restaura una oportunidad para volver a trabajar con ella.</p></div><button class="btn" data-page="Oportunidades">Ver oportunidades</button></div><div class="toolbar"><div class="search"><input id="search" aria-label="Buscar archivados" placeholder="Buscar empresa, contacto, teléfono o email…" value="${esc(query)}"></div></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Empresa</th><th>Contacto</th><th>Responsable</th><th>Archivada el</th><th>Acciones</th></tr></thead><tbody>${items.map(l=>`<tr><td><b>${esc(l.company_name)}</b></td><td>${esc(l.contact_name)}</td><td>${esc(person(l.owner_id))}</td><td>${dt(l.deleted_at)}</td><td><button class="btn small" data-open="${l.id}">Ver detalle</button> <button class="btn primary small" data-restore="${l.id}">Restaurar</button> <button class="btn danger small" data-delete-archived="${l.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${items.map(l=>`<article class="mobile-lead"><h3>${esc(l.company_name)}</h3><p>${esc(l.contact_name)} · ${esc(person(l.owner_id))}</p><p class="subtext">Archivada el ${dt(l.deleted_at)}</p><button class="btn small" data-open="${l.id}">Ver detalle</button> <button class="btn primary small" data-restore="${l.id}">Restaurar</button> <button class="btn danger small" data-delete-archived="${l.id}">Eliminar</button></article>`).join('')}</div>${items.length?'':`<div class="empty"><strong>${query?'Sin resultados':'No hay oportunidades archivadas'}</strong>${query?'Prueba con otra búsqueda.':'Las oportunidades que archives aparecerán aquí.'}</div>`}</section>`);
  wireCommon();
  document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));
  document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>restoreLead(archivedLeads.find(l=>l.id===b.dataset.restore)));
  document.querySelectorAll('[data-delete-archived]').forEach(b=>b.onclick=()=>deleteArchived(archivedLeads.find(l=>l.id===b.dataset.deleteArchived)));
}
async function restoreLead(lead){
  if(!isAdmin()||!lead)return;
  try{const {error}=await sb.from('leads').update({deleted_at:null}).eq('id',lead.id);if(error)throw error;await loadApp();notify('Oportunidad restaurada. Ya está disponible en Oportunidades.');}catch(e){notify(errText(e),true)}
}

function renderPipeline(items){setView(`<div class="page-head"><div><h1>Pipeline</h1><p>Arrastra una oportunidad a otra etapa para actualizarla.</p></div><button class="btn" data-page="Oportunidades">☷ Vista tabla</button></div>${filterBar()}<div class="kanban">${stages.map(([key,name])=>{const group=items.filter(l=>l.status===key);return `<section class="kanban-col" data-stage="${key}"><div class="kanban-title"><span>${name}</span><span>${group.length}</span></div>${group.map(l=>`<article class="lead-card" draggable="true" data-lead="${l.id}" data-open="${l.id}"><h3>${esc(l.company_name)}</h3><p>${esc(l.contact_name)}</p><div class="card-foot"><span>${money(l.estimated_value)}</span><span>${l.next_action_at?dt(l.next_action_at):'Sin seguimiento'}</span></div>${isAdmin()?`<p class="subtext">${esc(person(l.owner_id))}</p>`:''}${idleDays(l)>=3&&activeStatus(l.status)?`<p class="subtext">Requiere atención · ${idleDays(l)>=14?'14+':idleDays(l)>=7?'7+':idleDays(l)} días</p>`:''}</article>`).join('')}</section>`}).join('')}</div>`);wireCommon();document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>{if(!window.__dragging)openDetail(el.dataset.open)});document.querySelectorAll('.lead-card').forEach(card=>{card.ondragstart=e=>{window.__dragging=true;e.dataTransfer.setData('text/plain',card.dataset.lead);card.classList.add('dragging')};card.ondragend=()=>{card.classList.remove('dragging');setTimeout(()=>window.__dragging=false,0)}});document.querySelectorAll('.kanban-col').forEach(col=>{col.ondragover=e=>e.preventDefault();col.ondrop=async e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');const lead=leads.find(l=>l.id===id);if(lead&&lead.status!==col.dataset.stage)await changeStage(lead,col.dataset.stage)}})}
function renderFollowups(){
 const pending=followups.filter(f=>f.status==='pending'&&leads.some(l=>l.id===f.lead_id&&!l.deleted_at));const groups=dayGroups(pending);const overdue=pending.filter(f=>new Date(f.due_at)<new Date());const today=groups.today.filter(f=>new Date(f.due_at)>=new Date());
 setView(`<div class="page-head"><div><h1>Seguimientos</h1><p>Una sola agenda, conectada a tus oportunidades. Horario de Ecuador.</p></div><button class="btn primary" id="new-followup">＋ Crear seguimiento</button></div>${[['Vencidos',overdue],['Para hoy',today],['Próximos',groups.upcoming]].map(([title,list])=>`<section class="panel followup-panel"><div class="panel-head"><h2>${title}</h2><span class="badge">${list.length}</span></div>${list.map(taskRow).join('')||'<div class="empty"><strong>Todo al día.</strong>No tienes seguimientos pendientes en este grupo.</div>'}</section>`).join('')}`);
 document.querySelector('#new-followup').onclick=()=>chooseFollowup();wireTasks();
}
function renderCommissions(){const rows=commissions.filter(c=>isAdmin()||c.executive_id===profile.id);const gen=rows.reduce((a,c)=>a+Math.round(Number(c.generated_amount||0)*100),0)/100,paid=rows.reduce((a,c)=>a+Math.round(Number(c.paid_amount||0)*100),0)/100,pending=rows.reduce((a,c)=>a+Math.round(Number(c.pending_amount||0)*100),0)/100;setView(`<div class="page-head"><div><h1>Comisiones</h1><p>Cada venta conserva su tasa. La comisión se genera solo por cobros confirmados.</p></div></div><div class="grid stats"><article class="stat"><div class="stat-label">Comisión generada</div><div class="stat-value">${money(gen)}</div></article><article class="stat"><div class="stat-label">Comisión pagada</div><div class="stat-value">${money(paid)}</div></article><article class="stat"><div class="stat-label">Pendiente de pago</div><div class="stat-value">${money(pending)}</div></article><article class="stat"><div class="stat-label">Tasa para nuevas ventas</div><div class="stat-value">${Math.round(commissionRate*100)}%</div></article></div><section class="panel"><div class="table-wrap"><table class="data-table" style="display:table;min-width:580px"><thead><tr><th>Proyecto</th>${isAdmin()?'<th>Colaborador</th>':''}<th>Valor vendido</th><th>Cobrado</th><th>Generada</th><th>Pagada</th><th>Pendiente</th>${isAdmin()?'<th></th>':''}</tr></thead><tbody>${rows.map(c=>{const sale=sales.find(s=>s.id===c.sale_id)||{lead_id:c.lead_id,total_value:c.total_value,collected_amount:c.collected_amount},lead=[...leads,...archivedLeads].find(l=>l.id===sale?.lead_id);return `<tr><td><b>${esc(lead?.company_name||c.company_name||'Proyecto')}</b><span class="subtext">${date(sale?.signed_at)} · ${Math.round(c.rate*100)}%</span></td>${isAdmin()?`<td>${esc(person(c.executive_id))}</td>`:''}<td>${money(sale?.total_value)}</td><td>${money(sale?.collected_amount)}</td><td>${money(c.generated_amount)}</td><td>${money(c.paid_amount)}</td><td><b>${money(c.pending_amount)}</b></td>${isAdmin()?`<td>${Number(c.pending_amount)>0?`<button class="btn small" data-pay-commission="${c.id}">Registrar pago</button>`:''}</td>`:''}</tr>`}).join('')}</tbody></table></div>${rows.length?'':`<div class="empty"><strong>Todavía no hay comisiones</strong>Al confirmar cobros de proyectos ganados, el cálculo aparecerá aquí.</div>`}</section>`);document.querySelectorAll('[data-pay-commission]').forEach(b=>b.onclick=()=>openCommissionPayment(b.dataset.payCommission));}
