 const [ar,hr]=await Promise.all([sb.from('activities').select('*').eq('lead_id',id).order('occurred_at',{ascending:false}).limit(40),sb.from('lead_audit_log').select('*').eq('lead_id',id).order('created_at',{ascending:false}).limit(40)]);
 if(ar.error||hr.error){notify(errText(ar.error||hr.error),true);return;}
 const sale=sales.find(s=>s.lead_id===id),commission=commissions.find(c=>c.sale_id===sale?.id),tasks=followups.filter(f=>f.lead_id===id&&f.status==='pending'),readOnly=Boolean(lead.deleted_at);
 const facts=[['Contacto',lead.contact_name],['Cargo',lead.job_title],['Teléfono',lead.phone],['Email',lead.email],['Web',lead.website],['Servicio',lead.services?.name],['Fuente',lead.source],['Valor estimado',money(lead.estimated_value)],['Responsable',person(lead.owner_id)],['Registrado por',person(lead.created_by)],['Fecha de creación',dt(lead.created_at)],['Última actividad',dt(lead.last_contact_at)],['Próxima acción',tasks[0]?.description],['Próximo seguimiento',dt(tasks[0]?.due_at)]];
 const root=modal(esc(lead.company_name),`<div class="detail-grid"><div>${readOnly?'<div class="notice">Esta oportunidad está archivada. Puedes consultar su historial o restaurarla.</div>':''}<div class="field"><label for="detail-stage">Estado de oportunidad</label><select id="detail-stage" ${readOnly?'disabled':''}>${stages.map(([key,label])=>`<option value="${key}" ${key===lead.status?'selected':''}>${label}</option>`).join('')}</select></div><div class="quick-actions">${!readOnly?`<button class="btn small" id="edit-lead">Editar</button>${activityTypes.map(([key,label])=>`<button class="btn small" data-activity="${key}">${label}</button>`).join('')}${lead.status!=='lost'?'<button class="btn primary small" id="add-followup">＋ Seguimiento</button>':''}${lead.status==='won'&&!sale?'<button class="btn primary small" id="close-value">Registrar valor final</button>':''}`:''}</div><div class="detail-facts">${facts.map(([label,value])=>`<div class="fact"><label>${label}</label><b>${esc(value||'—')}</b></div>`).join('')}</div>${lead.notes?`<p class="detail-notes">${esc(lead.notes)}</p>`:''}${isAdmin()&&!readOnly?`<details class="detail-options"><summary>Administrar oportunidad</summary><div class="field"><label>Reasignar responsable</label><select id="reassign">${profiles.filter(p=>p.is_active).map(p=>`<option value="${p.id}" ${p.id===lead.owner_id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select></div><button class="btn danger small" id="archive-lead">Archivar oportunidad</button></details>`:''}${readOnly?'<button class="btn primary" id="restore-lead">Restaurar oportunidad</button>':''}${sale?`<section class="panel finance-panel"><div class="panel-head"><h2>Venta y cobros</h2>${isAdmin()&&!readOnly&&sale.pending_balance>0?'<button class="btn small" id="add-payment">＋ Cobro</button>':''}</div><div class="detail-facts">${[['Valor final',sale.total_value],['Cobrado',sale.collected_amount],['Saldo pendiente',sale.pending_balance]].map(([label,value])=>`<div class="fact"><label>${label}</label><b>${money(value)}</b></div>`).join('')}${commission?`<div class="fact"><label>Comisión (${Math.round(commission.rate*100)}%)</label><b>${money(commission.generated_amount)}</b><span class="subtext">Pagada ${money(commission.paid_amount)} · Pendiente ${money(commission.pending_amount)}</span></div>`:''}</div>${isAdmin()&&commission?.pending_amount>0&&!readOnly?`<button class="btn small" id="pay-commission">Pagar comisión</button>`:''}${payments.filter(p=>p.sale_id===sale.id).map(p=>`<div class="payment-row"><span>${date(p.paid_at)} · ${esc(p.payment_method||'Pago')}<small>${p.status==='confirmed'?'Confirmado':p.status==='pending'?'Pendiente':'Cancelado'}${p.reference?' · '+esc(p.reference):''}</small></span><b>${money(p.amount)}</b>${isAdmin()&&!readOnly&&p.status!=='cancelled'?`<div>${p.status==='pending'?`<button class="btn small" data-payment="${p.id}" data-status="confirmed">Confirmar</button>`:''}<button class="btn danger small" data-payment="${p.id}" data-status="cancelled">Cancelar</button></div>`:''}</div>`).join('')}</section>`:''}</div><div><section class="panel"><div class="panel-head"><h2>Seguimientos pendientes</h2></div>${tasks.map(taskRow).join('')||'<div class="empty"><strong>Todo al día.</strong>No hay seguimientos pendientes.</div>'}</section><section class="panel finance-panel"><div class="panel-head"><h2>Actividad comercial</h2></div>${ar.data.length?`<div class="timeline">${ar.data.filter(a=>a.type!=='task').map(a=>`<div class="timeline-item"><b>${esc(activityLabel(a.type))} · ${esc(person(a.created_by))}</b><p>${esc(a.subject)}${a.body?`<br>${esc(a.body)}`:''}</p><time>${dt(a.occurred_at)}</time></div>`).join('')}</div>`:'<div class="empty">Registra una llamada, mensaje o nota para empezar.</div>'}</section><section class="panel finance-panel"><div class="panel-head"><h2>Historial del sistema</h2></div>${renderHistory(hr.data)}</section></div></div>`,{wide:true});
 root.querySelector('#restore-lead')?.addEventListener('click',()=>restoreLead(lead));if(readOnly)return;
 root.querySelector('#detail-stage').onchange=e=>changeStage(lead,e.target.value);
